Register Individual.code:
// Register a new individual (e.g. from a field enrolment form).
// Every record needs at least one identifier: system is the ID type's namespace URI.
createIndividual({
  identifier: [{ system: 'urn:openspp:vocab:id-type#national_id', value: 'SL-2001' }], // e.g. $.data.nationalId
  name: { family: 'Bangura', given: 'Fatima' },
  birthDate: '1992-04-11',
  gender: { coding: [{ system: 'urn:iso:std:iso:5218', code: '2' }] }, // ISO 5218: 1 male, 2 female
  telecom: [{ system: 'phone', value: '+23276000123' }],
});
// The created Individual is in state.data.

Register Household Group.code:
// Register a household.
createGroup({
  identifier: [{ system: 'urn:openspp:vocab:id-type#household_id', value: 'HH-BAN-01' }], // e.g. $.data.householdId
  name: 'Bangura Household',
  groupType: 'household', // household | family | organization | other
});

Add Member To Household.code:
// Add an individual to a household as a child.
// Throws a 409 error if they're already a member; use request() with PATCH
// /Group/{group}/member/{individual} to change an existing member's role.
addToGroup(
  'urn:openspp:vocab:id-type#household_id|HH-SES-01',
  'urn:openspp:vocab:id-type#national_id|SL-1004',
  'child' // a code from urn:openspp:vocab:group-membership-type, e.g. head, spouse, child
);

Remove Member From Household.code:
// End a membership, e.g. when someone moves out. The end date defaults to now.
removeFromGroup(
  'urn:openspp:vocab:id-type#household_id|HH-KAM-01',
  'urn:openspp:vocab:id-type#national_id|SL-1002',
  { reason: 'Moved out' }
);

Update Individual.code:
// Correct a date of birth. This is a JSON Merge Patch: fields you leave out
// stay as they are, and null clears a field.
updateIndividual('urn:openspp:vocab:id-type#national_id|SL-1003', {
  birthDate: '1990-02-21',
});

Enroll In Program.code:
// Enroll an individual in a program. Beneficiaries are references:
// 'Individual/system|value' or 'Group/system|value'.
// If they are already enrolled, the existing membership is returned unchanged.
enroll(
  'Individual/urn:openspp:vocab:id-type#national_id|SL-1004',
  'urn:openspp:program|school-feeding'
);

Unenroll From Program.code:
// Exit a household from a program at the end of the month.
unenroll(
  'Group/urn:openspp:vocab:id-type#household_id|HH-KAM-01',
  'urn:openspp:program|cash-transfer-2024',
  { exitDate: '2026-09-30' }
);

Get Individual.code:
// Fetch an individual by external identifier (system|value).
// elements trims the response to the fields you need.
getIndividual('urn:openspp:vocab:id-type#national_id|SL-1001', { elements: ['identifier', 'name', 'birthDate'] });

Search Individuals.code:
// Children born since 2010 in the Kamara family, 50 per page.
// Results are in state.data; state.response.page has { total, next }.
searchIndividual(
  { name: 'Kamara', birthdate: 'ge2010-01-01' },
  { count: 50, offset: 0 }
);

Get Individual's Households.code:
// request() reaches any /api/v2/spp endpoint. Identifiers in paths must be URL-encoded.
request(
  'GET',
  `/Individual/${encodeURIComponent('urn:openspp:vocab:id-type#national_id|SL-1001')}/groups`
);
